#!/usr/bin/env python3
"""Build field-level dictionaries and mark monetary aggregation boundaries explicitly."""
import csv,json,re
from acquire import ROOT,DATA,save_json
j=json.loads((DATA/'raw/usaspending_docs/data_dictionary.json').read_text())['document'];defs={}
for row in j['rows']:
 for index in [7,9,11]:
  for field in re.split(r'[,\n]',str(row[index] or '')):
   if field.strip():defs[field.strip()]=row[1]
def monetary(k):return any(x in k.lower() for x in ['_amount','_value','obligation','obligated','outlay','loan_subsidy_cost']) and not k.endswith(('_code','_description','_name'))
def semantics(k,kind):
 if k=='indirect_cost_federal_share_amount':return 'federal award action amount allocated to approved indirect costs','USD','Component of federal funding, not additional funding. Do not add to action obligation.'
 if k=='total_non_federal_funding_amount':return 'overall assistance award amount funded by nonfederal sources','USD','Overall award measure repeated on actions; not federal spending and not a transaction change.'
 if k=='total_face_value_of_loan':return 'sum of face/principal values across all transactions of the loan award','USD','Overall loan principal measure, not subsidy cost or federal obligation; loan types excluded here.'
 if k=='generated_pragmatic_obligations':return 'USAspending derived spending measure: loan subsidy for loan types, federal action obligation otherwise; null defaults to zero','USD','Derived duplicate of action obligation for all 88,273 research-grant actions checked. Never add it to federal_action_obligation. Formula: official transaction_search.py mapping.'
 if 'highly_compensated_officer' in k:return 'reported executive compensation','USD','Never an award amount; do not include in investment totals.'
 if k=='federal_action_obligation':return 'signed federal obligation change on this transaction','USD','May sum only unique transactions in a defined action-date universe; retain negative deobligations; deduplicate overlapping extracts.'
 if k in ['base_and_exercised_options_value','base_and_all_options_value']:return ('transaction contract-value field; '+('base plus exercised options' if 'exercised' in k else 'base plus all options, including unexercised')),'USD','Modification values can be signed changes; not payments or interchangeable with obligations. See official definition and verify base/modification context.'
 if k in ['current_total_value_of_award','potential_total_value_of_award']:return ('overall award current value (base/exercised)' if k.startswith('current') else 'overall award potential value including all options'),'USD','Award-level value as reported on an action, potentially varying across modifications; do not sum rows. The official current-value definition uses the word obligated, but this field is kept distinct from federal_action_obligation and total_dollars_obligated.'
 if k=='subaward_amount':return 'prime-recipient reported first-tier subaward amount','USD','Do not add to prime spending or assume modification increments. Check report revisions and cumulative/duplicate reporting.'
 if k=='prime_award_amount':return 'overall prime award amount copied onto subaward rows','USD','Repeated parent-award measure; never sum subaward rows to estimate prime funding.'
 if 'outlay' in k:return 'overall award reported outlays'+(' from named supplemental funding' if 'supplemental' in k else ''),'USD','Award-level snapshot repeated across transactions/subawards, not action-date payments. Before FY2022 reporting may be incomplete. Do not add to obligations.'
 if k in ['total_dollars_obligated','total_obligated_amount']:return 'cumulative overall-award federal obligations across actions','USD','Repeated snapshot, not the obligation of this row. Select one appropriate vintage per award; do not sum across transaction rows.'
 if 'obligat' in k and 'supplemental' in k:return 'overall-award cumulative obligations funded by named supplemental','USD','Subset of overall obligations, repeated on rows. Do not add to total obligations or across transactions.'
 if k=='non_federal_funding_amount':return 'nonfederal share reported for assistance action','USD','Not federal expenditure. Do not add to federal obligations as federal investment.'
 if k=='total_funding_amount':return 'federal action obligation plus nonfederal assistance funding','USD','Mixed financing measure; not exclusively federal spending; retain action and revision context.'
 if k=='face_value_of_loan':return 'face value/principal of loan or loan guarantee','USD','Not an obligation/outlay measure of subsidy cost; loans not targeted in this pass.'
 if 'loan_subsidy_cost' in k:return 'estimated long-term government cost of loan support','USD','Distinct from face value; loans not targeted in this pass.'
 return 'Use official definition; no safe aggregation assumed','USD','Do not aggregate until grain, currency and time basis reviewed.'
rows=[];fields=[]
for p in sorted((ROOT/'validation').glob('*_schemas.json')):
 source=p.name.removesuffix('_schemas.json')
 for member,cols in json.loads(p.read_text()).items():
  kind='subaward' if 'Subawards' in member else 'transaction'
  for k in cols:
   fields.append({'source':source,'member':member,'field':k,'official_definition':defs.get(k,''),'definition_source':'https://api.usaspending.gov/api/v2/references/data_dictionary/'})
   if monetary(k):
    meaning,unit,rule=semantics(k,kind);rows.append({'source':source,'member_kind':kind,'field':k,'meaning':meaning,'unit':unit,'aggregation_rule':rule,'official_definition':defs.get(k,''),'definition_source':'https://api.usaspending.gov/api/v2/references/data_dictionary/'})
extras=[
 ('financial_actions','unique_transaction','action_obligation_usd','Signed federal_action_obligation from one preferred representation per native transaction key','USD_decimal128_23_2','Duplicate view of source actions, not additional money. Use this OR corresponding source transactions. Negative deobligations retained; no amount totals computed. Eligibility/coverage restrictions remain.','https://api.usaspending.gov/api/v2/references/data_dictionary/'),
 ('sbir_current','award','Award Amount','Amount of the reported SBIR/STTR award','USD','Not a transaction history or outlay. Phase I/II awards, revisions and duplicate records require review; may overlap USAspending contract/grant.','https://www.sbir.gov/data-resources/data-dictionary'),
 ('grants','opportunity','AwardCeiling','Expected maximum individual award amount in an opportunity','USD','Funding intent, not award or obligation. Zero may mean unspecified; do not treat as realized funding.','https://www.grants.gov/xml-extract'),
 ('grants','opportunity','AwardFloor','Expected minimum individual award amount in an opportunity','USD','Funding intent; not additive to ceiling or program funding.','https://www.grants.gov/xml-extract'),
 ('grants','opportunity','EstimatedTotalProgramFunding','Estimated available program funding advertised','USD','May cover multiple expected awards. Not committed money or award-size ceiling.','https://www.grants.gov/xml-extract'),
 ('omb_budget','account_year_vintage','amount_usd / value_in_source_units','Net budget authority or net outlays, explicitly separate measure field','USD / USD_thousands','Source values in thousands, net of offsetting collections; receipts can be negative. FY2019-25 actuals in PB2027, FY2026 estimated. Never add measures or vintages.','https://www.whitehouse.gov/wp-content/uploads/2026/04/db_guide_fy2027.pdf'),
 ('darpa_budget','program_title_in_exhibit','FY2023/FY2024/FY2025_*_millions','Program funding column in PB2025 R-2/R-2A exhibit','USD_millions','Prior/current-year reported exhibit amounts and FY2025 request. Not assumed obligations/outlays. PE/project/program totals nest; cross-PE references can duplicate capability representations.','https://www.darpa.mil/sites/default/files/attachment/2024-11/u-rdte-mjb-darpa-pb-2025-06-mar-2024-final.pdf'),
 ('commons','project_header','disclosed_project_amount_raw / amount_usd','Project amount disclosed in technology-area sheet; time basis unspecified','USD_millions / USD_thousands / unspecified','Only explicit M/k scaled. One $1.10 unit unspecified remains null in amount_usd. No assumption of obligation, outlay or lifecycle budget; cross-collection overlap possible.','https://www.cto.mil/ct/microelectronics/commons/'),
 ('apfit','selected_project','selected_project_funding_usd','Report states $10M selected funding per FY2022 project','USD','Selection/allocated procurement funding disclosure; not a transaction obligation/payment. Do not add to matching USAspending award.','https://calvert.house.gov/sites/evo-subsites/calvert.house.gov/files/evo-media-document/20230321-apfit-biannual-report.pdf'),
 ('doe_ldrd','laboratory_fiscal_year','doe_cost_millions / spp_cost_millions / total_cost_millions / ldrd_cost_millions','DOE-funded and Strategic Partnership Projects laboratory costs, total cost base, and internal LDRD cost','USD_millions','LDRD is an institutional expenditure funded through laboratory overhead, not new federal awards. LDRD costs are included in broader cost bases. Total row nests laboratory rows; never add both. Rate is percent; project count is not money.','https://www.energy.gov/cfo/listings/laboratory-directed-research-and-development-annual-reports'),
 ('ffrdc','institution_question_dimension_year','data','Separately accounted R&D expenditure reported for organization fiscal year 2025; questionnaire sections 1-3','USD_thousands','Source/agency/type breakdowns and total rows describe same expenditure. Do not add across dimensions or to grants/contracts; organization fiscal year may differ from federal FY.','https://ncses.nsf.gov/1919/assets/0/files/srvyrdexpenditures-2025-ffrdc.pdf'),
 ('federal_funds','published_table_cell','cells_json','Published federal R&D obligations/outlays or percentage, depending on table, row and column','per_table_units_header','Some tables thousands, others millions or percent. FY2025 preliminary; historical years revised. Positional rows retain headers/footnotes; do not sum across overlapping tables.','https://ncses.nsf.gov/pubs/nsf26316'),
 ('*_pages','document_page','uninterpreted_currency_mentions','Literal strings mentioned in PDF page','uninterpreted','These are evidence strings, not numeric measures. Page amounts may be nested totals, quantities, report preparation cost, procurement funding, authorizations, requests or plans.','downloaded source PDF')]
for source,kind,field,meaning,unit,rule,url in extras:rows.append({'source':source,'member_kind':kind,'field':field,'meaning':meaning,'unit':unit,'aggregation_rule':rule,'official_definition':'','definition_source':url})
for name,data in [('monetary_fields.csv',rows),('source_fields.csv',fields)]:
 with (ROOT/'validation'/name).open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
save_json(ROOT/'design/canonical_record_schema.json',{'format':'Each canonical scalar is UTF-8 string or null; money/identifiers/tags use JSON-encoded strings in Parquet/JSONL for uniform Arrow schema. Source tables preserve richer original schemas.','fields':{'document_id':'Source + stable identity/content hash; exact source duplicates may repeat; no row-number-only identity. PDF uses snapshot SHA256 + page.','source_record_id':'Source-provided key or documented composite; may collide across revisions','award_key':'Source-native composite award key; for SBIR contract alone is not globally sufficient','transaction_key':'USAspending transaction unique key; not a prime/subaward key','entity_key':'UEI preferred; legacy DUNS fallback; do not assume identifier equivalence','source_url':'Record link when available; otherwise source portal plus raw locator','raw_locator':'Filename + CSV data row, source key, XML opportunity ID or PDF physical page','text':'Source narrative, never model rewrite','money_json':'Source field names and string decimal values; dictionary determines grain and unit','eligibility':'Candidate/intent/context flags, not editorial inclusion decision','capability_tags':'Transparent regex features, not novelty or quality scoring','identifiers_json':'Original keys, agency/branch, solicitation and topic references where available','record_sha256':'Hash of canonicalized raw CSV row','source_snapshot_sha256':'Raw file hash; source snapshot/vintage boundary','action_date':'Source action date, opportunity posting date or SBIR performance-start date; semantics vary by source','retrieved_at':'UTC retrieval timestamp, not effective/award/publication date'}})
print('money dictionary',len(rows),'source fields',len(fields))
